// The Form node's expression sandbox can't run real code (no Error constructor,
// no throw), so the dropdown is built here in a Code node and the form page
// just reads the finished JSON string.
const d = $input.first().json.data || {};
// Brand statuses: analyzing | ready | logo_required | failed. Only 'ready' can generate.
const brands = (d.brands || []).filter((b) => !b.status || b.status === 'ready');
if (!brands.length) {
  throw new Error('No ready brands on this Bloom account. Create one at https://www.trybloom.ai/brands, wait for onboarding to finish, then run again.');
}
return [{
  json: {
    formFieldsJson: JSON.stringify([{
      fieldLabel: 'Brand',
      fieldType: 'dropdown',
      requiredField: true,
      fieldOptions: {
        values: brands.map((b) => ({ option: (b.name || b.url || 'Unnamed brand') + ' (' + b.id + ')' })),
      },
    }]),
  },
}];

// Combine the submitted blog post with the brand picked on the second form
// page. The blog text and the platform captions are the user's own copy and
// flow through untouched: this workflow only generates the images.
const sel = String($input.first().json['Brand'] || '');
const m = sel.match(/\(([^()]+)\)\s*$/);
if (!m) {
  throw new Error('Could not read the brand id from the dropdown value: ' + sel);
}
const brandId = m[1];
const d = $('Bloom: fetch your brands').first().json.data || {};
const brand = (d.brands || []).find((b) => b.id === brandId) || {};
const form = $('Form: paste your post + captions').first().json;
return [{
  json: {
    brand_session_id: brandId,
    brand_name: brand.name || 'Your brand',
    title: form['Blog title'],
    body: form['Blog body'],
    captions: {
      instagram: form['Instagram caption'] || '',
      linkedin: form['LinkedIn caption'] || '',
      twitter: form['Twitter/X caption'] || '',
    },
  },
}];

// No LLM in the loop: each platform's image brief is a fixed template that
// describes that platform's audience and composition, with the user's own
// copy (title + caption) injected as subject matter. The in-image headline
// is the blog title, so even the words inside the image are the user's.
const post = $('Normalize input (post + brand id)').first().json;

// Render guidance appended to every image prompt. Brand styling (colors, typography,
// aesthetic) is deliberately not prompted: Bloom's brand layer applies it via brandSessionId,
// and restating it in the prompt duplicates or fights that layer.
const BRAND_GUIDANCE =
  'Render the headline inside the image, bold and legible. ' +
  'One clear focal point.';

const SCENES = {
  main: 'A wide editorial hero image for the blog post itself. Depict the single most concrete subject of the post (an object, place, or process named in it), composed with clear space for the headline. Photograph or illustration.',
  instagram: 'A single-subject close-up for an Instagram feed: one object or moment from the post, framed tight and vertical, instantly readable at thumbnail size between personal photos.',
  linkedin: 'A square composition for a LinkedIn audience reading in a professional context: the subject of the post shown in its work or process setting, like a still from a well-shot documentary about the craft.',
  twitter: 'A bold, high-contrast composition for a fast-scrolling X timeline: one focal subject from the post, large in the frame, readable in half a second at small size.',
};

// Aspect ratio + output filename are assigned deterministically per platform.
// Captions are the user's own copy from the form, passed through untouched.
const platforms = [
  { platform: 'main',      aspectRatio: '16:9', basename: 'blog-main', caption: '' },
  { platform: 'instagram', aspectRatio: '4:5',  basename: 'instagram', caption: post.captions.instagram },
  { platform: 'linkedin',  aspectRatio: '1:1',  basename: 'linkedin',  caption: post.captions.linkedin },
  { platform: 'twitter',   aspectRatio: '16:9', basename: 'twitter',   caption: post.captions.twitter },
];

// The blog hero has no caption, so it leans on the opening of the post instead.
const excerpt = String(post.body || '').replace(/\s+/g, ' ').slice(0, 400);

return platforms.map((p) => {
  const copy = p.caption || excerpt;
  return {
    json: {
      platform: p.platform,
      aspectRatio: p.aspectRatio,
      basename: p.basename,
      headline: post.title,
      caption: p.caption,
      image_prompt:
        SCENES[p.platform] +
        '\n\nThe post this image accompanies (subject matter only, do not render this text):\n"' + copy + '"\n\n' +
        'Headline: "' + post.title + '".\n' + BRAND_GUIDANCE,
    },
  };
});

