const main = byPlatform.main || {};
const ig = byPlatform.instagram || {};
const li = byPlatform.linkedin || {};
const tw = byPlatform.twitter || {};
const initial = esc((brand[0] || 'B').toUpperCase());
const today = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
const paragraphs = String(post.body || '').split(/\n+/).filter(Boolean).map((p) => `<p>${esc(p)}</p>`).join('');

// Stroke icons keep the action rows looking native without shipping image assets.
